from pathlib import Path
import json,sqlite3,time,sys

root=Path.home()/".local/share/prediction-project-executor/campaigns/FULL-A2Z-LIVE-20261004-V4"
models=root/"models"
dbp=models/"runtime.sqlite"
result=root/"model_results"/"A2Z-V4-SOL-BUILD-20261007-R4.json"
request=root/"requests"/"A2Z-V4-SOL-BUILD-20261007-R4.json"

out={"request_exists":request.exists(),"result_exists":result.exists()}
if dbp.exists():
    db=sqlite3.connect("file:"+str(dbp)+"?mode=ro",uri=True)
    try:
        row=db.execute("select status,attempt,run,thread from tasks where id=?",( "A2Z-V4-SOL-BUILD-20261007-R4", )).fetchone()
        trs=db.execute("select state,reason,attempt,checkpoint,next_action,stamp,retry from transitions where task=? order by seq desc limit 5",( "A2Z-V4-SOL-BUILD-20261007-R4", )).fetchall()
    finally:
        db.close()
    out["task_row"]=row
    out["transitions"]=trs
    if row and row[2]:
        cp=models/row[2]
        out["run_dir"]=str(cp)
        out["run_exists"]=cp.exists()
        if cp.exists():
            for n in ("TASK.json","WORKER.json","COMPLETE.json","events.jsonl","stderr.log","worker_error.json"):
                p=cp/n
                out[n]=p.exists()
            ep=cp/"events.jsonl"
            if ep.exists():
                lines=[x for x in ep.read_text(errors="replace").splitlines() if x.strip()]
                out["event_count"]=len(lines)
                out["last_event"]=lines[-1][:1200] if lines else ""
            wp=cp/"WORKER.json"
            if wp.exists():
                try:
                    w=json.loads(wp.read_text())
                    out["worker_model"]=w.get("model")
                    out["worker_started_at"]=w.get("started_at")
                except Exception as e:
                    out["worker_json_error"]=type(e).__name__+":"+str(e)
            ce=cp/"COMPLETE.json"
            if ce.exists():
                try:
                    c=json.loads(ce.read_text())
                    out["complete_task_id"]=c.get("task_id")
                    out["complete_attempt"]=c.get("attempt")
                    out["complete_has_final"]=bool(c.get("final"))
                except Exception as e:
                    out["complete_json_error"]=type(e).__name__+":"+str(e)
print("E126_STATE "+json.dumps(out,separators=(",",":"),default=str),flush=True)

if out.get("result_exists"):
    print("E126=R4_RESULT_EXISTS",flush=True); raise SystemExit(0)
row=out.get("task_row")
if not row:
    print("E126=TASK_ROW_MISSING",flush=True); raise SystemExit(31)
status=str(row[0])
if status=="PAUSED_USAGE_LIMIT":
    print("E126=PAUSED_USAGE_LIMIT",flush=True); raise SystemExit(20)
if status=="RUNNING":
    print("E126=RUNNING",flush=True); raise SystemExit(21)
if status=="COMPLETE":
    print("E126=COMPLETE_WITHOUT_RESULT",flush=True); raise SystemExit(22)
if status=="WAITING_RETRY":
    print("E126=WAITING_RETRY",flush=True); raise SystemExit(23)
print("E126=STATE_"+status,flush=True); raise SystemExit(29)
